namespace fs = std::filesystem;

static const char* PROXY_CONFIG_DIR = "/var/run/proxy";
static const char* PROXY_CERT_CACHE = "/var/run/proxy/certs";
static const char* K8S_SERVICE_ACCOUNT = "/var/run/secrets/kubernetes.io/serviceaccount/token";

class CertificateRotator {
public:
    CertificateRotator(const std::string& cache_dir) : cache_dir_(cache_dir), running_(false) {
        // Open the cache directory fd for use with openat()
        cache_dir_fd_ = open(cache_dir.c_str(), O_RDONLY | O_DIRECTORY | O_NOFOLLOW);
    }

    ~CertificateRotator() {
        if (cache_dir_fd_ >= 0) close(cache_dir_fd_);
    }

    void start() {
        running_ = true;
        rotation_thread_ = std::thread(&CertificateRotator::rotation_loop, this);
    }

    void stop() {
        running_ = false;
        if (rotation_thread_.joinable()) rotation_thread_.join();
    }

    std::string get_cert_path(const std::string& hostname) const {
        return cache_dir_ + "/" + sanitize_hostname(hostname) + ".pem";
    }

    bool ensure_cert_cached(const std::string& hostname) {
        std::string sanitized = sanitize_hostname(hostname);
        std::string cert_filename = sanitized + ".pem";
        std::string tmp_filename = sanitized + ".pem.tmp";

        // Check if cert already exists and is fresh using fstatat with AT_SYMLINK_NOFOLLOW
        struct stat st;
        if (fstatat(cache_dir_fd_, cert_filename.c_str(), &st, AT_SYMLINK_NOFOLLOW) == 0) {
            // Reject symlinks entirely
            if (S_ISLNK(st.st_mode)) {
                std::cerr << "Symlink detected in cert cache, removing: " << cert_filename << std::endl;
                unlinkat(cache_dir_fd_, cert_filename.c_str(), 0);
                return false;
            }
            time_t now = time(nullptr);
            if (now - st.st_mtime < 3600) {
                return true; // cert is fresh
            }
        }

        // Fetch new cert from internal CA
        std::string cert_data = fetch_cert_from_ca(hostname);
        if (cert_data.empty()) return false;

        // Write to temp file using openat with O_NOFOLLOW to prevent symlink following
        int fd = openat(cache_dir_fd_, tmp_filename.c_str(),
                       O_WRONLY | O_CREAT | O_TRUNC | O_NOFOLLOW, 0644);
        if (fd < 0) return false;

        // Ensure the full buffer is written; handle partial writes.
        const char* data_ptr = cert_data.c_str();
        size_t remaining = cert_data.size();
        bool write_ok = true;
        while (remaining > 0) {
            ssize_t written = write(fd, data_ptr, remaining);
            if (written <= 0) {
                write_ok = false;
                break;
            }
            data_ptr += written;
            remaining -= static_cast<size_t>(written);
        }
        close(fd);

        if (!write_ok) {
            // Do not promote a partially-written cert file.
            unlinkat(cache_dir_fd_, tmp_filename.c_str(), 0);
            return false;
        }

        // Atomic rename within the same directory
        renameat(cache_dir_fd_, tmp_filename.c_str(), cache_dir_fd_, cert_filename.c_str());
        return true;
    }

    int get_cache_dir_fd() const { return cache_dir_fd_; }

private:
    std::string cache_dir_;
    int cache_dir_fd_;
    std::atomic<bool> running_;
    std::thread rotation_thread_;

    static std::string sanitize_hostname(const std::string& hostname) {
        std::string result;
        for (char c : hostname) {
            if (std::isalnum(c) || c == '.' || c == '-') {
                result += c;
            }
        }
        return result;
    }

    std::string fetch_cert_from_ca(const std::string& hostname) {
        // Simulated CA fetch - in production this calls the mesh CA
        return "-----BEGIN CERTIFICATE-----\nMIIB...simulated...\n-----END CERTIFICATE-----\n";
    }

    void rotation_loop() {
        while (running_) {
            std::this_thread::sleep_for(std::chrono::seconds(300));
            rotate_expired_certs();
        }
    }

    void rotate_expired_certs() {
        if (!fs::exists(cache_dir_)) return;
        for (auto& entry : fs::directory_iterator(cache_dir_)) {
            if (entry.path().extension() == ".pem") {
                struct stat st;
                // Use fstatat with AT_SYMLINK_NOFOLLOW to detect symlinks
                std::string filename = entry.path().filename().string();
                if (fstatat(cache_dir_fd_, filename.c_str(), &st, AT_SYMLINK_NOFOLLOW) == 0) {
                    if (S_ISLNK(st.st_mode)) {
                        // Remove rogue symlinks
                        unlinkat(cache_dir_fd_, filename.c_str(), 0);
                        continue;
                    }
                    time_t now = time(nullptr);
                    if (now - st.st_mtime >= 3600) {
                        std::string hostname = entry.path().stem().string();
                        ensure_cert_cached(hostname);
                    }
                }
            }
        }
    }
};

class ProxyConnectionHandler {
public:
    ProxyConnectionHandler(CertificateRotator& rotator) : rotator_(rotator) {}

    void handle_connection(int client_fd, const std::string& target_host, int target_port) {
        // Ensure we have a valid cert for the target
        if (!rotator_.ensure_cert_cached(target_host)) {
            std::cerr << "Failed to cache cert for " << target_host << std::endl;
            close(client_fd);
            return;
        }

        std::string sanitized = sanitize_hostname(target_host);
        std::string cert_filename = sanitized + ".pem";

        // Open cert using openat with O_NOFOLLOW to prevent symlink attacks
        int cert_fd = openat(rotator_.get_cache_dir_fd(), cert_filename.c_str(),
                            O_RDONLY | O_NOFOLLOW);
        if (cert_fd < 0) {
            std::cerr << "Failed to open cert (possible symlink attack)" << std::endl;
            close(client_fd);
            return;
        }

        // Verify it's a regular file after opening
        struct stat st;
        if (fstat(cert_fd, &st) != 0 || !S_ISREG(st.st_mode)) {
            std::cerr << "Cert is not a regular file" << std::endl;
            close(cert_fd);
            close(client_fd);
            return;
        }

        // Read cert content from the verified fd, handling partial reads.
        std::string cert_content;
        cert_content.resize(st.st_size);
        size_t total_read = 0;
        bool read_ok = true;
        while (total_read < static_cast<size_t>(st.st_size)) {
            ssize_t n = read(cert_fd, &cert_content[total_read],
                             static_cast<size_t>(st.st_size) - total_read);
            if (n < 0) {
                read_ok = false;
                break;
            }
            if (n == 0) break; // EOF
            total_read += static_cast<size_t>(n);
        }
        close(cert_fd);

        if (!read_ok) {
            std::cerr << "Failed to read cert content" << std::endl;
            close(client_fd);
            return;
        }
        cert_content.resize(total_read);

        // Establish upstream connection with loaded cert
        establish_upstream(client_fd, target_host, target_port, cert_content);
    }

private:
    CertificateRotator& rotator_;

    static std::string sanitize_hostname(const std::string& hostname) {
        std::string result;
        for (char c : hostname) {
            if (std::isalnum(c) || c == '.' || c == '-') {
                result += c;
            }
        }
        return result;
    }

    void establish_upstream(int client_fd, const std::string& host, int port,
                           const std::string& cert_data) {
        // In production: use cert_data for mTLS handshake
        // Forward connection to upstream service
        int upstream_fd = socket(AF_INET, SOCK_STREAM, 0);
        if (upstream_fd < 0) {
            std::cerr << "Failed to create upstream socket" << std::endl;
            close(client_fd);
            return;
        }

        struct sockaddr_in upstream_addr{};
        upstream_addr.sin_family = AF_INET;
        upstream_addr.sin_port = htons(port);

        // Validate that host is a well-formed IPv4 address before connecting;
        // otherwise sin_addr would remain 0.0.0.0 and we could connect somewhere
        // unintended.
        if (inet_pton(AF_INET, host.c_str(), &upstream_addr.sin_addr) != 1) {
            std::cerr << "Invalid upstream address: " << host << std::endl;
            close(upstream_fd);
            close(client_fd);
            return;
        }

        if (connect(upstream_fd, (struct sockaddr*)&upstream_addr, sizeof(upstream_addr)) < 0) {
            close(client_fd);
            close(upstream_fd);
            return;
        }

        // Bidirectional proxy (simplified)
        char buf[4096];
        ssize_t n = recv(client_fd, buf, sizeof(buf), 0);
        if (n > 0) send(upstream_fd, buf, n, 0);
        n = recv(upstream_fd, buf, sizeof(buf), 0);
        if (n > 0) send(client_fd, buf, n, 0);

        close(upstream_fd);
        close(client_fd);
    }
};

int main(int argc, char* argv[]) {
    // Initialize cache directory
    fs::create_directories(PROXY_CERT_CACHE);

    CertificateRotator rotator(PROXY_CERT_CACHE);
    rotator.start();

    ProxyConnectionHandler handler(rotator);

    // Listen for proxy connections
    int server_fd = socket(AF_INET, SOCK_STREAM, 0);
    struct sockaddr_in addr{};
    addr.sin_family = AF_INET;
    addr.sin_addr.s_addr = INADDR_ANY;
    addr.sin_port = htons(8443);

    bind(server_fd, (struct sockaddr*)&addr, sizeof(addr));
    listen(server_fd, 128);

    std::cout << "Proxy listening on :8443" << std::endl;

    while (true) {
        struct sockaddr_in client_addr{};
        socklen_t client_len = sizeof(client_addr);
        int client_fd = accept(server_fd, (struct sockaddr*)&client_addr, &client_len);
        if (client_fd < 0) continue;

        // Read target host from PROXY protocol header (simplified)
        char buf[256] = {};
        recv(client_fd, buf, sizeof(buf) - 1, 0);
        std::string target_host(buf);

        std::thread([&handler, client_fd, target_host]() {
            handler.handle_connection(client_fd, target_host, 443);
        }).detach();
    }

    rotator.stop();
    return 0;
}
